from threading import Lock


def _is_integer(value):
    return isinstance(value, int) and not isinstance(value, bool)


class RateLimiter:
    def __init__(self, rate: int, per_seconds: float, clock=None):
        if not _is_integer(rate) or rate <= 0:
            raise ValueError("rate must be a positive integer")
        if (
            isinstance(per_seconds, bool)
            or not isinstance(per_seconds, (int, float))
            or per_seconds <= 0
        ):
            raise ValueError("per_seconds must be positive")

        self._rate = rate
        self._per_seconds = float(per_seconds)
        self._capacity = rate
        self._clock = time.monotonic if clock is None else clock
        self._lock = Lock()
        self._buckets = {}

    def _refill(self, bucket, now):
        if now > bucket[1]:
            elapsed = now - bucket[1]
            bucket[0] = min(
                float(self._capacity),
                bucket[0] + elapsed * self._rate / self._per_seconds,
            )
            bucket[1] = now

    def allow(self, key, cost: int = 1) -> bool:
        if not _is_integer(cost) or cost <= 0 or cost > self._rate:
            raise ValueError("cost must be a positive integer no greater than rate")

        with self._lock:
            now = self._clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self._capacity), now]
                self._buckets[key] = bucket
            else:
                self._refill(bucket, now)

            if bucket[0] + 1e-12 >= cost:
                bucket[0] = max(0.0, bucket[0] - cost)
                return True
            return False

    def state(self, key) -> dict:
        with self._lock:
            now = self._clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self._capacity), now]
                self._buckets[key] = bucket
            else:
                self._refill(bucket, now)

            return {
                "tokens": round(bucket[0], 3),
                "capacity": self._capacity,
            }

    def reset(self, key) -> None:
        with self._lock:
            self._buckets[key] = [float(self._capacity), self._clock()]
